{
  "name": "defu",
  "version": "6.1.4",
  "description": "Recursively assign default properties. Lightweight and Fast!",
  "type": "module",
  "license": "MIT",
  "repository": "unjs/defu",
  "main": "src/defu.ts",
  "exports": {
    ".": "./src/defu.ts"
  },
  "scripts": {
    "test": "vitest run",
    "check-types": "tsc --noEmit"
  },
  "devDependencies": {
    "@types/bun": "latest"
  }
}

import { isPlainObject } from "./_utils";
import type { Merger, DefuFn as DefuFunction, DefuInstance } from "./types";

// Base function to apply defaults
function _defu<T>(baseObject: T, defaults: any, namespace = ".", merger?: Merger): T {
  if (!isPlainObject(defaults)) {
    return _defu(baseObject, {}, namespace, merger);
  }

  const object = Object.assign({}, defaults);

  for (const key in baseObject) {
    if (key === "__proto__" || key === "constructor") {
      continue;
    }

    const value = baseObject[key];

    if (value === null || value === undefined) {
      continue;
    }

    if (merger && merger(object, key, value, namespace)) {
      continue;
    }

    if (Array.isArray(value) && Array.isArray(object[key])) {
      object[key] = [...value, ...object[key]];
    } else if (isPlainObject(value) && isPlainObject(object[key])) {
      object[key] = _defu(
        value,
        object[key],
        (namespace ? `${namespace}.` : "") + key.toString(),
        merger,
      );
    } else {
      object[key] = value;
    }
  }

  return object;
}

// Create defu wrapper with optional merger and multi arg support
export function createDefu(merger?: Merger): DefuFunction {
  return (...arguments_) =>
    // eslint-disable-next-line unicorn/no-array-reduce
    arguments_.reduce((p, c) => _defu(p, c, "", merger), {} as any);
}

// Standard version
export const defu = createDefu() as DefuInstance;
export default defu;

// Custom version with function merge support
export const defuFn = createDefu((object, key, currentValue) => {
  if (object[key] !== undefined && typeof currentValue === "function") {
    object[key] = currentValue(object[key]);
    return true;
  }
});

// Custom version with function merge support only for defined arrays
export const defuArrayFn = createDefu((object, key, currentValue) => {
  if (Array.isArray(object[key]) && typeof currentValue === "function") {
    object[key] = currentValue(object[key]);
    return true;
  }
});

export type { Defu } from "./types";

// Forked from sindresorhus/is-plain-obj (MIT)
// Copyright (c) Sindre Sorhus <sindresorhus@gmail.com> (https://sindresorhus.com)
export function isPlainObject(value: unknown): boolean {
  if (value === null || typeof value !== "object") {
    return false;
  }
  const prototype = Object.getPrototypeOf(value);

  if (
    prototype !== null &&
    prototype !== Object.prototype &&
    Object.getPrototypeOf(prototype) !== null
  ) {
    return false;
  }

  if (Symbol.iterator in value) {
    return false;
  }

  if (Symbol.toStringTag in value) {
    return Object.prototype.toString.call(value) === "[object Module]";
  }

  return true;
}

export type Input = Record<string | number | symbol, any>;
export type IgnoredInput = boolean | number | null | any[] | Record<never, any> | undefined;

export type Merger = <T extends Input, K extends keyof T>(
  object: T,
  key: keyof T,
  value: T[K],
  namespace: string,
) => any;

type nullish = null | undefined | void;

export type MergeObjects<
  Destination extends Input,
  Defaults extends Input,
> = Destination extends Defaults
  ? Destination
  : Omit<Destination, keyof Destination & keyof Defaults> &
      Omit<Defaults, keyof Destination & keyof Defaults> & {
        -readonly [Key in keyof Destination & keyof Defaults]: Destination[Key] extends nullish
          ? Defaults[Key] extends nullish
            ? nullish
            : Defaults[Key]
          : Defaults[Key] extends nullish
            ? Destination[Key]
            : Merge<Destination[Key], Defaults[Key]>; // eslint-disable-line no-use-before-define
      };

export type Defu<S extends Input, D extends Array<Input | IgnoredInput>> = D extends [
  infer F,
  ...infer Rest,
]
  ? F extends Input
    ? Rest extends Array<Input | IgnoredInput>
      ? Defu<MergeObjects<S, F>, Rest>
      : MergeObjects<S, F>
    : F extends IgnoredInput
      ? Rest extends Array<Input | IgnoredInput>
        ? Defu<S, Rest>
        : S
      : S
  : S;

export type DefuFn = <Source extends Input, Defaults extends Array<Input | IgnoredInput>>(
  source: Source,
  ...defaults: Defaults
) => Defu<Source, Defaults>;

export interface DefuInstance {
  <Source extends Input, Defaults extends Array<Input | IgnoredInput>>(
    source: Source | IgnoredInput,
    ...defaults: Defaults
  ): Defu<Source, Defaults>;
  fn: DefuFn;
  arrayFn: DefuFn;
  extend(merger?: Merger): DefuFn;
}

export type MergeArrays<Destination, Source> =
  Destination extends Array<infer DestinationType>
    ? Source extends Array<infer SourceType>
      ? Array<DestinationType | SourceType>
      : Source | Array<DestinationType>
    : Source | Destination;

export type Merge<Destination extends Input, Defaults extends Input> =
  // Remove explicitly null types
  Destination extends nullish
    ? Defaults extends nullish
      ? nullish
      : Defaults
    : Defaults extends nullish
      ? Destination
      : // Handle arrays
        Destination extends Array<any>
        ? Defaults extends Array<any>
          ? MergeArrays<Destination, Defaults>
          : Destination | Defaults
        : // Don't attempt to merge Functions, RegExps, Promises
          // eslint-disable-next-line @typescript-eslint/ban-types
          Destination extends Function
          ? Destination | Defaults
          : Destination extends RegExp
            ? Destination | Defaults
            : Destination extends Promise<any>
              ? Destination | Defaults
              : // Don't attempt to merge Functions, RegExps, Promises
                // eslint-disable-next-line @typescript-eslint/ban-types
                Defaults extends Function
                ? Destination | Defaults
                : Defaults extends RegExp
                  ? Destination | Defaults
                  : Defaults extends Promise<any>
                    ? Destination | Defaults
                    : // Ensure we only merge Records
                      Destination extends Input
                      ? Defaults extends Input
                        ? MergeObjects<Destination, Defaults>
                        : Destination | Defaults
                      : Destination | Defaults;

import { describe, test, expect } from "vitest";
import { defu, createDefu } from "../src/defu.ts";

describe("defu regression", () => {
  test("copies missing defaults", () => {
    const result = defu({ a: "c" }, { a: "bbb", d: "c" });
    expect(result).toEqual({ a: "c", d: "c" });
  });

  test("fills null values from defaults", () => {
    const result = defu({ a: null as any }, { a: "c", d: "c" });
    expect(result).toEqual({ a: "c", d: "c" });
  });

  test("merges nested objects", () => {
    const result = defu({ a: { b: "c" } }, { a: { d: "e" } });
    expect(result).toEqual({ a: { b: "c", d: "e" } });
  });

  test("concats arrays by default", () => {
    const result = defu({ array: ["a", "b"] }, { array: ["c", "d"] });
    expect(result).toEqual({ array: ["a", "b", "c", "d"] });
  });

  test("multi defaults", () => {
    const result = defu({ a: 1 }, { b: 2, a: "x" }, { c: 3, a: "x", b: "x" });
    expect(result).toEqual({ a: 1, b: 2, c: 3 });
  });

  test("handles non-object defaults", () => {
    expect(defu({ d: true } as any, null as any)).toEqual({ d: true });
    expect(defu(null as any, { d: true })).toEqual({ d: true });
  });

  test("does not override Object prototype via constructor", () => {
    const payload = JSON.parse('{"constructor": {"prototype": {"isAdmin": true}}}');
    defu({}, payload);
    defu(payload, {});
    defu(payload, payload);
    // @ts-ignore
    expect(({} as any).isAdmin).toBe(undefined);
  });
});

#!/usr/bin/env node
// V1 helper for file-based hypothesis/evidence tracking inside workspace.
// Usage:
//   node .v1/helpers.js add-hypothesis '{"description":"...","evidence":["file:line"],"confidence":0.8,"files":["src/foo.ts"]}'
//   node .v1/helpers.js select-hypothesis <id>
//   node .v1/helpers.js add-evidence '{"type":"file_inspection","description":"...","source":"src/foo.ts","result":"supports"}'
//   node .v1/helpers.js add-file-inspected src/foo.ts
//   node .v1/helpers.js add-command '{"command":"npm test","exitCode":0,"stdout":"..."}'
//   node .v1/helpers.js add-verification '{"method":"vitest","command":"vitest run","passed":true,"output":"..."}'
//   node .v1/helpers.js status
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { join, dirname } from "node:path";
import { randomUUID } from "node:crypto";

const STATE_PATH = join(process.cwd(), ".v1/state.json");

function load() {
  if (!existsSync(STATE_PATH)) {
    console.error("No .v1/state.json found at", STATE_PATH);
    process.exit(1);
  }
  const raw = readFileSync(STATE_PATH, "utf-8");
  return JSON.parse(raw);
}
function save(s) {
  mkdirSync(dirname(STATE_PATH), { recursive: true });
  writeFileSync(STATE_PATH, JSON.stringify(s, null, 2), "utf-8");
}

const cmd = process.argv[2];
if (!cmd || cmd === "help" || cmd === "--help") {
  console.log("Usage: node .v1/helpers.js <add-hypothesis|select-hypothesis|add-evidence|add-file-inspected|add-command|add-verification|status>");
  process.exit(0);
}
if (cmd === "status") {
  const s = load();
  console.log(JSON.stringify(s, null, 2));
  process.exit(0);
}
if (cmd === "add-hypothesis") {
  const arg = process.argv[3];
  if (!arg) { console.error("need JSON arg"); process.exit(1); }
  let payload;
  try { payload = JSON.parse(arg); } catch { payload = { description: arg, evidence: [] }; }
  const s = load();
  const h = {
    id: payload.id ?? `hyp-${randomUUID().slice(0, 8)}`,
    description: payload.description ?? "hypothesis",
    evidence: payload.evidence ?? [],
    confidence: payload.confidence ?? 0.5,
    status: payload.status ?? "active",
    files: payload.files,
  };
  s.hypotheses = s.hypotheses ?? [];
  s.hypotheses.push(h);
  // also push evidence entry for diagnosis
  s.evidence = s.evidence ?? [];
  s.evidence.push({ id: `ev-${randomUUID().slice(0, 8)}`, type: "other", description: `Hypothesis: ${h.description}`, source: h.files?.[0], result: "neutral", timestamp: new Date().toISOString(), phase: s.phase });
  save(s);
  console.log(h.id);
  process.exit(0);
}
if (cmd === "select-hypothesis") {
  const id = process.argv[3];
  if (!id) { console.error("need id"); process.exit(1); }
  const s = load();
  let found = false;
  for (const hyp of s.hypotheses) {
    if (hyp.id === id) { hyp.status = "selected"; s.selectedHypothesis = id; found = true; }
    else if (hyp.status === "selected") hyp.status = "active";
  }
  if (!found) { console.error("hypothesis not found", id); process.exit(1); }
  save(s);
  console.log("selected", id);
  process.exit(0);
}
if (cmd === "add-evidence") {
  const arg = process.argv[3];
  let payload;
  try { payload = JSON.parse(arg); } catch { payload = { description: arg }; }
  const s = load();
  s.evidence = s.evidence ?? [];
  s.evidence.push({ id: `ev-${randomUUID().slice(0, 8)}`, type: payload.type ?? "other", description: payload.description ?? arg, source: payload.source, result: payload.result ?? "neutral", timestamp: new Date().toISOString(), phase: payload.phase ?? s.phase });
  save(s);
  console.log("evidence added");
  process.exit(0);
}
if (cmd === "add-file-inspected") {
  const p = process.argv[3];
  const s = load();
  s.filesInspected = s.filesInspected ?? [];
  if (!s.filesInspected.includes(p)) s.filesInspected.push(p);
  save(s);
  console.log("file recorded", p);
  process.exit(0);
}
if (cmd === "add-command") {
  // raw json {command, exitCode, stdout, stderr, durationMs}
  const arg = process.argv.slice(3).join(" ");
  let payload;
  try { payload = JSON.parse(arg); } catch { payload = { command: arg }; }
  const s = load();
  s.commandsExecuted = s.commandsExecuted ?? [];
  s.commandsExecuted.push({ command: payload.command ?? arg, exitCode: payload.exitCode ?? null, stdout: payload.stdout ?? "", stderr: payload.stderr ?? "", durationMs: payload.durationMs ?? 0, phase: s.phase, timestamp: new Date().toISOString() });
  save(s);
  console.log("command recorded");
  process.exit(0);
}
if (cmd === "add-verification") {
  const arg = process.argv.slice(3).join(" ");
  let payload;
  try { payload = JSON.parse(arg); } catch { payload = { method: arg, output: arg }; }
  const s = load();
  s.verificationAttempts = s.verificationAttempts ?? [];
  s.verificationAttempts.push({ id: `ver-${randomUUID().slice(0, 8)}`, iteration: s.iteration, method: payload.method ?? "manual", command: payload.command, passed: payload.passed ?? null, output: payload.output ?? JSON.stringify(payload), timestamp: new Date().toISOString(), phase: s.phase });
  if (payload.passed !== undefined || payload.output) {
    s.evidence = s.evidence ?? [];
    s.evidence.push({ id: `ev-${randomUUID().slice(0, 8)}`, type: payload.type ?? "test_result", description: `Verification: ${payload.method ?? payload.command ?? "check"}`, source: payload.command, result: payload.passed ? "supports" : payload.passed === false ? "contradicts" : "neutral", timestamp: new Date().toISOString(), phase: s.phase });
  }
  save(s);
  console.log("verification recorded");
  process.exit(0);
}
console.error("unknown command", cmd);
process.exit(1);

